// The owner's own number guides and Number Notes (server/number-guide.json, GENERATED by tools/make-number-guide.mjs):
// every number has its card, words as written, and the meaning page carries it for the spot and each diamond behind it.
import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import { meaningFor, guideFor } from '../server/meaning.js';

const { numbers } = JSON.parse(fs.readFileSync(new URL('../server/number-guide.json', import.meta.url), 'utf8'));

test('every number 1-99 has a card; every one but 93 (not in the 46-99 Guide) has the guide', () => {
  for (let n = 1; n <= 99; n++) {
    const g = numbers[n];
    assert.ok(g, `no card for ${n}`);
    if (n === 93) { assert.ok(!g.name && g.notes.length); continue; }
    assert.ok(g.name && g.intro && g.groups.some((x) => x.title === 'Balanced Manifestation'), `${n}: guide incomplete`);
    assert.doesNotMatch(g.name + g.alt, /[ð\u0080-\u009f]/, `${n}: emoji left in the title`);
  }
});

test('35/8 is the 10-45 Guide as written, plus the owner\'s notes, each note once', () => {
  const g = numbers[35];
  assert.equal(g.name, 'The Chieftain'); assert.equal(g.alt, 'Here And No Further!'); assert.equal(g.book, '10-45 Guide');
  assert.match(g.groups.find((x) => x.title === 'Little Diamond').points[0], /^With an outer drive for success \(3\)/);
  assert.ok(g.notes.some((x) => x.title === '35/8, 62/8 or 26/8'));
  const all = g.notes.flatMap((x) => x.points).map((t) => t.toLowerCase().replace(/[^a-z0-9]/g, ''));
  assert.equal(new Set(all).size, all.length);
});

test('the meaning page carries the guide for the spot and for each diamond behind it', () => {
  const m = meaningFor({ chart: 'name', position: 'heart', sum: 12, rel: [{ position: 'heartSubDiamond', sum: 35 }] });
  assert.equal(m.guide.name, guideFor(12).name);
  assert.equal(m.related[0].guide.name, 'The Chieftain');
});
